package test;

import org.eclipse.jdt.ui.PreferenceConstants;
import org.eclipse.jface.preference.IPreferenceStore;

public class TestClass {
    public void setupDefaults(IPreferenceStore store) {
        store.setDefault(PreferenceConstants.EDITOR_CODEMINING_ENABLED, false);
        store.setDefault(PreferenceConstants.EDITOR_JAVA_CODEMINING_SHOW_CODEMINING_AT_LEAST_ONE, true);
        store.setDefault(PreferenceConstants.EDITOR_JAVA_CODEMINING_SHOW_REFERENCES, false); 
        store.setDefault(PreferenceConstants.EDITOR_JAVA_CODEMINING_SHOW_REFERENCES_ON_CLASSES, true);
        store.setDefault(PreferenceConstants.EDITOR_JAVA_CODEMINING_SHOW_REFERENCES_ON_FIELDS, false);
        store.setDefault(PreferenceConstants.EDITOR_JAVA_CODEMINING_SHOW_REFERENCES_ON_METHODS, true);
        store.setDefault(PreferenceConstants.EDITOR_JAVA_CODEMINING_SHOW_IMPLEMENTATIONS, false); 
    }
}

